fn run() { target(first: 1, 2); }
}

seiyaku ArgumentTableBound { struct B0 { bool bit; } struct B1 { B0 left; B0 right; } struct B2 { B1 left; B1 right; } struct B3 { B2 left; B2 right; } struct B4 { B3 left; B3 right; } struct B5 { B4 left; B4 right; } struct B6 { B5 left; B5 right; } struct B7 { B6 left; B6 right; } struct B8 { B7 left; B7 right; } struct B9 { B8 left; B8 right; } struct B10 { B9 left; B9 right; } struct B11 { B10 left; B10 right; } struct B12 { B11 left; B11 right; } struct B13 { B12 left; B12 right; } struct B14 { B13 left; B13 right; }
fn too_wide(B14 value) -> bool { return true; }
view fn main() authorize(anyone) -> bool { return true; }
}

seiyaku InitHook {
state int total;
init() { total = 0; }
}

seiyaku HookShape {
state int total;
fn hajimari() { total = 0; }
}

seiyaku Retired {
view fn here() authorize(anyone) -> AccountId { return context::seiyaku_address(); }
view fn which() authorize(anyone) -> Name { return context::entrypoint(); }
}

seiyaku Variant {
error enum VaultError { ZeroDeposit = 1 }
fn check(int amount) { require(amount > 0, VaultError::ZeroDepsit); }
}

seiyaku ViewWrite {
state int count;
hajimari() { count = 0; }
view fn bump() authorize(anyone) -> int {
count += 1;
return count;
}
}

seiyaku Dropped {
fn check() -> int {
var List<int, 4> values = [1, 2];
values.try_push(3);
values.len()
}
}
